     1	export default function handler(req, res) {
     2	  const { id } = req.query
     3	
     4	  if (req.method === 'GET') {
     5	    // Simulate fetching a single post
     6	    const post = {
     7	      id: parseInt(id),
     8	      title: `Post ${id}`,
     9	      content: `This is the content for post ${id}`,
    10	      createdAt: new Date().toISOString(),
    11	    }
    12	
    13	    res.status(200).json(post)
    14	  } else if (req.method === 'PUT') {
    15	    const { title, content } = req.body
    16	
    17	    // Simulate updating a post
    18	    const updatedPost = {
    19	      id: parseInt(id),
    20	      title: title || `Post ${id}`,
    21	      content: content || `Updated content for post ${id}`,
    22	      updatedAt: new Date().toISOString(),
    23	    }
    24	
    25	    res.status(200).json(updatedPost)
    26	  } else if (req.method === 'DELETE') {
    27	    // Simulate deleting a post
    28	    res.status(200).json({ message: `Post ${id} deleted successfully` })
    29	  } else {
    30	    res.setHeader('Allow', ['GET', 'PUT', 'DELETE'])
    31	    res.status(405).end(`Method ${req.method} Not Allowed`)
    32	  }
    33	}
