import type { Metadata } from 'next'
import { headers } from 'next/headers'
import Link from 'next/link'
import { NavigateButton } from '../components/NavigateButton'
import type { Post } from '../types/blog'

export const metadata: Metadata = {
  title: 'Home - My Blog',
  description: 'Welcome to my blog homepage',
  openGraph: {
    title: 'Home - My Blog',
  },
}

// `cache: 'no-store'` keeps this request-time only, like `getServerSideProps`.
async function getRecentPosts(): Promise<Post[]> {
  const res = await fetch(
    'https://jsonplaceholder.typicode.com/posts?_limit=5',
    { cache: 'no-store' }
  )

  if (!res.ok) {
    throw new Error(`Failed to load recent posts: ${res.status}`)
  }

  return res.json()
}

export default async function HomePage() {
  // `headers()` is async in Next.js 16 and replaces `getServerSideProps`' `req`.
  const headersList = await headers()
  const userAgent = headersList.get('user-agent') || ''
  const posts = await getRecentPosts()
  const timestamp = new Date().toISOString()

  return (
    <div>
      <h1>Welcome to My Blog</h1>
      <p>Server-side rendered at: {timestamp}</p>
      <p>Your user agent: {userAgent}</p>

      <h2>Recent Posts</h2>
      <ul>
        {posts.map((post) => (
          <li key={post.id}>
            <Link href={`/blog/${post.id}`}>{post.title}</Link>
          </li>
        ))}
      </ul>

      <NavigateButton href="/blog">View All Posts</NavigateButton>
    </div>
  )
}

