import type { Metadata } from 'next'
import { notFound } from 'next/navigation'
import { BackButton } from '../../../components/BackButton'
import type { Comment, Post } from '../../../types/blog'

interface BlogPostParams {
  id: string
}

interface BlogPostProps {
  params: Promise<BlogPostParams>
}

// Replaces `fallback: 'blocking'`: ids that aren't returned by
// `generateStaticParams` are rendered on demand and then cached.
export const dynamicParams = true

// Replaces `getStaticPaths`.
export async function generateStaticParams(): Promise<BlogPostParams[]> {
  const res = await fetch('https://jsonplaceholder.typicode.com/posts')
  const posts: Post[] = await res.json()

  return posts.slice(0, 10).map((post) => ({ id: post.id.toString() }))
}

// The `fetch` calls below are memoized per request, so `generateMetadata` and the
// page itself share a single request. `next: { revalidate: 300 }` replaces
// `getStaticProps` + `revalidate: 300`.
async function getPost(id: string): Promise<Post | null> {
  const res = await fetch(`https://jsonplaceholder.typicode.com/posts/${id}`, {
    next: { revalidate: 300 },
  })

  if (!res.ok) {
    return null
  }

  return res.json()
}

async function getComments(id: string): Promise<Comment[]> {
  const res = await fetch(
    `https://jsonplaceholder.typicode.com/posts/${id}/comments`,
    { next: { revalidate: 300 } }
  )

  if (!res.ok) {
    return []
  }

  return res.json()
}

export async function generateMetadata({
  params,
}: BlogPostProps): Promise<Metadata> {
  const { id } = await params
  const post = await getPost(id)

  if (!post) {
    return { title: 'Post Not Found - My Blog' }
  }

  const description = post.body.substring(0, 160)

  return {
    title: `${post.title} - My Blog`,
    description,
    openGraph: {
      title: post.title,
      description,
    },
  }
}

export default async function BlogPostPage({ params }: BlogPostProps) {
  // `params` is a promise in Next.js 16.
  const { id } = await params
  const [post, comments] = await Promise.all([getPost(id), getComments(id)])

  // Replaces `return { notFound: true }` from `getStaticProps`.
  if (!post) {
    notFound()
  }

  return (
    <article>
      <BackButton>← Back</BackButton>

      <h1>{post.title}</h1>
      <p>{post.body}</p>

      <h2>Comments ({comments.length})</h2>
      <div className="comments">
        {comments.map((comment) => (
          <div key={comment.id} className="comment">
            <h3>{comment.name}</h3>
            <p>{comment.body}</p>
            <small>By: {comment.email}</small>
          </div>
        ))}
      </div>
    </article>
  )
}

