import { useEffect } from 'react'

// Replaces `pages/_error.js` for errors thrown below the root layout. There is no
// `statusCode` in the App Router — unmatched routes render `not-found.tsx`, and
// this boundary handles unexpected runtime errors instead.
export default function Error({
  error,
  retry,
}: {
  error: Error & { digest?: string }
  retry: () => void
}) {
  useEffect(() => {
    console.error(error)
  }, [error])

  return (
    <div className="error-page">
      <h1>An error occurred</h1>
      <p>Sorry, something went wrong.</p>
      <button type="button" onClick={() => retry()}>
        Try again
      </button>
    </div>
  )
}

