// Handles errors thrown by the root layout itself, which `error.tsx` cannot catch.
// This file replaces the root layout when active, so it renders its own document
// and imports its own global styles. `metadata` is not supported in Client
// Components, so the title is set with React's `<title>` element.
export default function GlobalError({
  error,
  retry,
}: {
  error: Error & { digest?: string }
  retry: () => void
}) {
  useEffect(() => {
    console.error(error)
