import type { NextRequest } from 'next/server'
import type { ApiPost, UpdatePostBody } from '../../../../types/api'

// `req.query.id` is now a dynamic route param, and `params` is a promise in
// Next.js 16.
interface PostRouteContext {
  params: Promise<{ id: string }>
}

export async function GET(request: NextRequest, { params }: PostRouteContext) {
  const { id } = await params

  // Simulate fetching a single post
  const post: ApiPost = {
    id: Number.parseInt(id, 10),
    title: `Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  }

  return Response.json(post)
}

export async function PUT(request: NextRequest, { params }: PostRouteContext) {
  const { id } = await params

  let body: UpdatePostBody = {}

  try {
    body = (await request.json()) as UpdatePostBody
  } catch {
    // An empty body is allowed: both fields fall back to defaults below.
  }

  // Simulate updating a post
  const updatedPost: ApiPost = {
    id: Number.parseInt(id, 10),
    title: body.title || `Post ${id}`,
    content: body.content || `Updated content for post ${id}`,
    updatedAt: new Date().toISOString(),
  }

  return Response.json(updatedPost)
}

export async function DELETE(request: NextRequest, { params }: PostRouteContext) {
  const { id } = await params

  // Simulate deleting a post
  return Response.json({ message: `Post ${id} deleted successfully` })
}

